import { useCallback, useState } from 'react';
import { TradeTokenLevelEnum, } from '../types/tradeTokenSchema';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { tradeTokenActions } from '../slice/tradeTokenSlice';
import { useGetPinCodeByPlatformUUID } from '05_entities/pinCode';
import { decodeString } from '06_shared/utils/cryptoJSUtils';
import { generateUUID } from '06_shared/utils/generateUUID';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useGetTradeTokenClient = (platform_uuid) => {
    const dispatch = useAppDispatch();
    const [isLoading, setIsLoading] = useState(false);
    const user = useGetMe();
    const pin_code = useGetPinCodeByPlatformUUID(platform_uuid);
    const getTradeTokenClient = useCallback(async () => {
        setIsLoading(true);
        try {
            if (!user) {
                dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
                return;
            }
            const trade_token_encoded_string = localStorage.getItem(platform_uuid);
            if (!trade_token_encoded_string) {
                dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
                return;
            }
            if (!pin_code) {
                const result = {
                    trade_token_uuid: generateUUID(),
                    platform_uuid: platform_uuid,
                    created_ts: Date.now(),
                    message: 'Please send PIN-Code for receive data about Trade Token',
                    level: TradeTokenLevelEnum.NO_PIN_CODE,
                };
                dispatch(tradeTokenActions.setTradeToken(result));
                return;
            }
            const key = `${pin_code}${user.user_trade_token_key}`;
            const trade_token_decoded_string = await decodeString(trade_token_encoded_string, key);
            const trade_token_decoded_dict = JSON.parse(trade_token_decoded_string);
            if (trade_token_decoded_dict) {
                const result = {
                    trade_token_uuid: trade_token_decoded_dict.trade_token_uuid,
                    platform_uuid: platform_uuid,
                    created_ts: new Date(trade_token_decoded_dict.created_at).getTime(),
                    updated_ts: trade_token_decoded_dict.updated_at
                        ? new Date(trade_token_decoded_dict.updated_at).getTime()
                        : undefined,
                    message: trade_token_decoded_dict.message,
                    level: TradeTokenLevelEnum.TRADE_AVAILABLE,
                };
                dispatch(tradeTokenActions.setTradeToken(result));
            }
        }
        catch {
            const result = {
                trade_token_uuid: generateUUID(),
                platform_uuid: platform_uuid,
                created_ts: Date.now(),
                message: 'Wrong PIN Code for reading Trade Token data',
                level: TradeTokenLevelEnum.WRONG_PIN_CODE,
            };
            dispatch(tradeTokenActions.setTradeToken(result));
        }
        finally {
            setIsLoading(false);
        }
    }, [dispatch, pin_code, platform_uuid, user]);
    return {
        getTradeTokenClient,
        isLoading,
    };
};
export { useGetTradeTokenClient };
