import { createSlice } from '@reduxjs/toolkit';
const initialState = {
    pin_code_dict: {},
};
export const pinCodeSlice = createSlice({
    name: 'pin_code',
    initialState,
    reducers: {
        setPinCode: (state, action) => {
            if (action.payload.pin_code) {
                state.pin_code_dict[action.payload.platform_uuid] = action.payload.pin_code;
            }
            else {
                delete state.pin_code_dict[action.payload.platform_uuid];
            }
        },
        resetPinCodeSlice() {
            return initialState;
        },
    }
});
export const { actions: pinCodeActions } = pinCodeSlice;
export const { reducer: pinCodeReducer } = pinCodeSlice;
