import { useCallback, useEffect } from 'react';
import { useLazyGetTradeTokenServerQuery } from '../api/tradeTokenApi';
import { tradeTokenActions } from '../slice/tradeTokenSlice';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { useGetPinCodeByPlatformUUID } from '05_entities/pinCode';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useGetTradeTokenServer = (platform_uuid) => {
    const dispatch = useAppDispatch();
    const [getToken, { data, isLoading, isError }] = useLazyGetTradeTokenServerQuery();
    const user = useGetMe();
    const pin_code = useGetPinCodeByPlatformUUID(platform_uuid);
    const getTradeTokenServer = useCallback(async () => {
        try {
            if (!user) {
                dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
                return;
            }
            const payload = {
                pin_code: pin_code,
                platform_uuid,
            };
            getToken(payload);
        }
        catch {
            dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
        }
    }, [dispatch, getToken, pin_code, platform_uuid, user]);
    useEffect(() => {
        if (data?.result) {
            dispatch(tradeTokenActions.setTradeToken(data.result));
        }
    }, [data, dispatch]);
    useEffect(() => {
        if (isError) {
            dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
        }
    }, [dispatch, isError, platform_uuid]);
    return {
        getTradeTokenServer,
        isLoading,
    };
};
export { useGetTradeTokenServer };
