import { useCallback, useState } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { tradeTokenActions } from '../slice/tradeTokenSlice';
import { pinCodeActions } from '05_entities/pinCode';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useRevokeTradeTokenClient = (platform_uuid) => {
    const dispatch = useAppDispatch();
    const [isLoading, setIsLoading] = useState(false);
    const user = useGetMe();
    const revokeTradeTokenClient = useCallback(async () => {
        setIsLoading(true);
        try {
            if (!user) {
                dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
                return;
            }
            localStorage.removeItem(platform_uuid);
            dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
            dispatch(pinCodeActions.setPinCode({ platform_uuid }));
        }
        catch (e) {
            console.log(e);
        }
        finally {
            setIsLoading(false);
        }
    }, [dispatch, platform_uuid, user]);
    return {
        revokeTradeTokenClient,
        isLoading,
    };
};
export { useRevokeTradeTokenClient };
