import { useCallback, useState } from 'react';
import { useAppDispatch } from '06_shared/hooks/useAppDispatch';
import { tradeTokenActions } from '../slice/tradeTokenSlice';
import { encodeString } from '06_shared/utils/cryptoJSUtils';
import { generateUUID } from '06_shared/utils/generateUUID';
import { useGetMe } from '06_shared/hooks/useGetMe';
const useCreateTradeTokenClient = (platform_uuid) => {
    const dispatch = useAppDispatch();
    const [isLoading, setIsLoading] = useState(false);
    const user = useGetMe();
    const createTradeTokenClient = useCallback(async (api_key, api_secret, pin_code) => {
        setIsLoading(true);
        try {
            if (!user) {
                dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
                return;
            }
            const key = `${pin_code}${user.user_trade_token_key}`;
            const trade_token_decoded_dict = {
                trade_token_uuid: generateUUID(),
                created_at: new Date().toISOString(),
                message: 'created new token',
                api_key,
                api_secret,
            };
            const trade_token_decoded_string = JSON.stringify(trade_token_decoded_dict);
            const trade_token_encoded_string = await encodeString(trade_token_decoded_string, key);
            localStorage.setItem(platform_uuid, trade_token_encoded_string);
        }
        catch {
            dispatch(tradeTokenActions.removeTradeToken(platform_uuid));
        }
        finally {
            setIsLoading(false);
        }
    }, [dispatch, platform_uuid, user]);
    return {
        createTradeTokenClient,
        isLoading,
    };
};
export { useCreateTradeTokenClient };
